-    if (((parameter_id - 27) % 31) == 0) {
+    if (IS_GREASE_QUIC(parameter_id)) {
         label = "GREASE";
     } else if (parameter_id > 0xffffffff) {
         // There are no 64-bit Parameter IDs at the moment.
